/** Holds the results of the concurrency scenario so each assertion can be isolated. */
private static final class ConcurrencyResult {
  final int adapterInstancesCreated;
  final TypeAdapter<?> adapter;
  final TypeAdapter<?> threadAdapter;

  ConcurrencyResult(int adapterInstancesCreated,
                    TypeAdapter<?> adapter,
                    TypeAdapter<?> threadAdapter) {
    this.adapterInstancesCreated = adapterInstancesCreated;
    this.adapter = adapter;
    this.threadAdapter = threadAdapter;
  }
}

/** Executes the original test logic and returns the collected data. */
private static ConcurrencyResult runGetAdapterConcurrency() {
  final AtomicInteger adapterInstancesCreated = new AtomicInteger(0);
  final AtomicReference<TypeAdapter<?>> threadAdapter = new AtomicReference<>();
  final Class<?> requestedType = Number.class;

  Gson gson = new GsonBuilder()
      .registerTypeAdapterFactory(
          new TypeAdapterFactory() {
            private volatile boolean isFirstCall = true;

            @Override
            public <T> TypeAdapter<T> create(final Gson gson, TypeToken<T> type) {
              if (isFirstCall) {
                isFirstCall = false;

                // Create a separate thread which requests an adapter for the same type.
                // This will cause this factory to return a different adapter instance than
                // the one it is currently creating.
                Thread thread = new Thread() {
                  @Override
                  public void run() {
                    threadAdapter.set(gson.getAdapter(requestedType));
                  }
                };
                thread.start();
                try {
                  thread.join();
                } catch (InterruptedException e) {
                  throw new RuntimeException(e);
                }
              }

              // Create a new dummy adapter instance.
              adapterInstancesCreated.incrementAndGet();
              return new DummyAdapter<>();
            }
          })
      .create();

  TypeAdapter<?> adapter = gson.getAdapter(requestedType);
  return new ConcurrencyResult(
      adapterInstancesCreated.get(),
