/**
 * Helper that obtains a {@link Field} via reflection. If the field cannot be
 * found, an {@link AssertionError} is thrown so the test fails with a clear
 * message instead of propagating a checked exception.
 */
private static Field getField(Class<?> clazz, String fieldName) {
    try {
        return clazz.getField(fieldName);
    } catch (NoSuchFieldException e) {
        throw new AssertionError(
            String.format("Expected field '%s' not found in class %s", fieldName, clazz.getName()), e);
    }
}

