/** Verifies the JSON structure written by the custom JsonWriter. */
@Test
public void testNewJsonWriter_Custom_JsonStructure() throws IOException {
  String output = writeCustomJson();

  // Strip the prefix and the trailing top‑level value to obtain the JSON object.
  String jsonPart =
      output.substring(")]}'\n".length(), output.length() - 1); // exclude final '1'

  JsonReader reader = new JsonReader(new StringReader(jsonPart));

  // The JSON should be an object with two members.
  reader.beginObject();

