/** Helper that writes a single double value as a JSON array and performs both
 *  string‑based and numeric assertions. */
private static void assertWritesDouble(double value, String expectedJsonNumber) {
    String json = writeArray(value);

    // Original behaviour – exact string representation.
    assertThat(json).isEqualTo("[" + expectedJsonNumber + "]");

    // Numeric check that does not depend on string formatting.
    try (JsonReader reader = new JsonReader(new StringReader(json))) {
        reader.beginArray();
        double actual = reader.nextDouble();
        // The writer should emit a value that is exactly the original double.
        assertThat(actual).isWithin(0.0).of(value);
        reader.endArray();
    } catch (IOException e) {
        // Convert the checked exception to a test failure without a throws clause.
        fail("Unexpected IOException while reading JSON: " + e.getMessage());
    }
}

/** Writes the given double value as a JSON array and returns the produced JSON string. */
private static String writeArray(double value) {
    try (StringWriter sw = new StringWriter(); JsonWriter jw = new JsonWriter(sw)) {
        jw.beginArray();
        jw.value(value);
        jw.endArray();
        jw.close();
        return sw.toString();
    } catch (IOException e) {
        // Turn the checked exception into an unchecked assertion error.
        throw new AssertionError("IOException while writing JSON", e);
    }
}

