/** Helper that builds the pretty‑printed JSON string, wrapping any {@link IOException}. */
private static String buildPrettyPrintedJson() {
  try {
    StringWriter stringWriter = new StringWriter();
    JsonWriter jsonWriter = new JsonWriter(stringWriter);
    jsonWriter.setIndent("   ");

    jsonWriter.beginObject();
    jsonWriter.name("a").value(true);
    jsonWriter.name("b").value(false);
    jsonWriter.name("c").value(5.0);
    jsonWriter.name("e").nullValue();
    jsonWriter.name("f").beginArray();
    jsonWriter.value(6.0);
    jsonWriter.value(7.0);
    jsonWriter.endArray();
    jsonWriter.name("g").beginObject();
    jsonWriter.name("h").value(8.0);
    jsonWriter.name("i").value(9.0);
    jsonWriter.endObject();
    jsonWriter.endObject();

    return stringWriter.toString();
  } catch (IOException e) {
    // In a test a failure to write is unexpected – turn it into an unchecked error.
    throw new AssertionError("Unexpected IOException while building JSON", e);
  }
}

/** Expected pretty‑printed JSON (kept as a literal for readability). */
private static final String EXPECTED_PRETTY_JSON =
    "{\n"
        + "   \"a\": true,\n"
