 * JSON string. This method is used by the refactored tests to keep the JSON‑generation logic
 * in a single place.
 */
private static String writeFloats(Float... values) throws IOException {
    StringWriter stringWriter = new StringWriter();
    JsonWriter jsonWriter = new JsonWriter(stringWriter);
    jsonWriter.beginArray();
    for (float v : values) {
        jsonWriter.value(v);
    }
    jsonWriter.endArray();
    jsonWriter.close();
    return stringWriter.toString();
}

/**
 * Verifies that the JSON representation produced by {@link JsonWriter} for a collection of
 * float values matches the exact expected string. This test focuses on the string formatting
 * aspect only, keeping it isolated from other concerns.
 */
@Test
public void testFloats_stringRepresentation() throws IOException {
    String json = writeFloats(
            -0.0f,
            1.0f,
            Float.MAX_VALUE,
            Float.MIN_VALUE,
            0.0f,
            -0.5f,
            2.2250739E-38f,
            3.723379f,
            (float) Math.PI,
            (float) Math.E);
    assertThat(json).isEqualTo(
            "[-0.0,1.0,3.4028235E38,1.4E-45,0.0,-0.5,2.2250739E-38,3.723379,3.1415927,2.7182817]");
}

/**
 * Checks that each individual float value written by {@link JsonWriter} can be read back
 * correctly. By parsing the JSON string into a {@link JsonArray} and comparing the numeric
 * values, we avoid brittle string‑based equality and test the actual data content.
 */
@Test
public void testFloats_valuesAreCorrect() throws IOException {
    String json = writeFloats(
            -0.0f,
            1.0f,
            Float.MAX_VALUE,
            Float.MIN_VALUE,
            0.0f,
            -0.5f,
            2.2250739E-38f,
            3.723379f,
            (float) Math.PI,
            (float) Math.E);
    JsonArray array = JsonParser.parseString(json).getAsJsonArray();

    float[] expected = {
            -0.0f,
            1.0f,
            Float.MAX_VALUE,
            Float.MIN_VALUE,
            0.0f,
            -0.5f,
            2.2250739E-38f,
            3.723379f,
            (float) Math.PI,
            (float) Math.E
    };

    assertThat(array.size()).isEqualTo(expected.length);
    for (int i = 0; i < expected.length; i++) {
        assertThat(array.get(i).getAsFloat()).isEqualTo(expected[i]);
    }
}

