/**
 * Helper that writes the supplied values to a JSON array using {@link JsonWriter}
 * and returns the resulting JSON string.
 */
private static String writeJsonArray(Object... values) throws IOException {
    StringWriter sw = new StringWriter();
    JsonWriter jw = new JsonWriter(sw);
    jw.beginArray();
    for (Object v : values) {
        if (v instanceof BigInteger) {
            jw.value((BigInteger) v);
        } else if (v instanceof BigDecimal) {
            jw.value((BigDecimal) v);
        } else {
            // Fallback for any other numeric type (not used in current tests)
            jw.value(v);
        }
    }
    jw.endArray();
    jw.close();
    return sw.toString();
}

