/**
 * Helper that creates a JSON string that spans across the internal buffer boundary.
 */
private static String jsonStringSpanningBuffers() {
  // Build a string that starts with '#', is padded with spaces to fill one buffer less three chars,
  // then adds the malformed JSON prefix followed by a number.
  StringBuilder sb = new StringBuilder("#");
  for (int i = 0; i < JsonReader.BUFFER_SIZE - 3; i++) {
    sb.append(' ');
  }
  sb.append("\n)]}'\n3");
  return sb.toString();
}

/**
