  JsonReader reader = new JsonReader(reader(json));
  reader.setStrictness(Strictness.LENIENT);
  return reader;
}

/**
 * Calls {@link JsonReader#peek()} and re‑throws any {@link IOException} as an unchecked exception.
 * This keeps the test method signature clean and removes explicit exception handling from the test.
 */
private static JsonToken peekUnchecked(JsonReader reader) {
  try {
    return reader.peek();
  } catch (IOException e) {
    throw new UncheckedIOException(e);
  }
}

/**
