 * number when the reader is in lenient mode.
 */
@Test
public void testReadAcrossBuffers() {
  JsonReader reader = lenientReader(jsonStringSpanningBuffers());
  JsonToken token = peekUnchecked(reader);
  assertThat(token).isEqualTo(JsonToken.NUMBER);
}

