 * {@link IllegalArgumentException} with the expected message.
 */
@ParameterizedTest(name = "malformed number: \"{0}\"")
@MethodSource("malformedNumbersProvider")
void testMalformedNumbers(String malformedNumber) {
    JsonWriter jsonWriter = new JsonWriter(new StringWriter());

    IllegalArgumentException exception = assertThrows(
        IllegalArgumentException.class,
        () -> jsonWriter.value(new LazilyParsedNumber(malformedNumber))
    );

    assertThat(exception)
        .hasMessageThat()
        .isEqualTo(MALFORMED_MESSAGE_PREFIX + malformedNumber);
}

