/** Helper that extracts all TextNode instances from the given document. */
private List<TextNode> getAllTextNodes(Document doc) {
    List<TextNode> textNodes = new ArrayList<>();
    for (Element el : doc.getAllElements()) {
        for (Node node : el.childNodes()) {
            if (node instanceof TextNode) {
                textNodes.add((TextNode) node);
            }
        }
    }
    return textNodes;
}

@Test
public void testHasTextWhenIterating_allTextNodesAreNonBlank() {
    Document doc = Jsoup.parse("<div>One <p>Two <p>Three");
    List<TextNode> textNodes = getAllTextNodes(doc);

    // Verify that at least one TextNode was found (pre‑condition for the loop below)
    assertFalse("No TextNode was found in the document", textNodes.isEmpty());

    // Verify that none of the collected TextNode texts are blank
    for (TextNode tn : textNodes) {
        assertFalse("Found a blank TextNode text", StringUtil.isBlank(tn.text()));
    }
}

@Test
public void testHasTextWhenIterating_firstTextNodeHasExpectedContent() {
    Document doc = Jsoup.parse("<div>One <p>Two <p>Three");
    List<TextNode> textNodes = getAllTextNodes(doc);

    // Guard against empty list – the previous test guarantees this, but we keep it explicit here.
    assertFalse("Document should contain at least one TextNode", textNodes.isEmpty());

    TextNode first = textNodes.get(0);
    assertEquals("One ", first.text());
    assertEquals("One ", first.getWholeText());
}

@Test
public void testHasTextWhenIterating_findsAtLeastOneTextNode() {
    Document doc = Jsoup.parse("<div>One <p>Two <p>Three");
    List<TextNode> textNodes = getAllTextNodes(doc);
    assertTrue("Expected to find at least one TextNode", !textNodes.isEmpty());
}

